 "content": "def transform(grid):
    """Extend a repeated horizontal motif's shorter row to its matching endpoint."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    # Rows with the same leftmost foreground position form corresponding motifs.
    groups = {}
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value != background]
        if cols:
            groups.setdefault(cols[0], []).append((r, cols[-1]))

    for rows in groups.values():
        target = max(right for _, right in rows)
        for r, right in rows:
            if right < target:
                for c in range(right + 1, target + 1):
                    if grid[r][c] == background:
                        out[r][c] = 1
    return out

if __name__ == '__main__':
    pass
